  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Unique email address used for authentication. Must be unique across all
  /// members.
  email String

  /// BCrypt or similar hashed password. Never stored in plaintext.
  password_hash String

  /// User's display name shown across the platform. Used for identification in
  /// activity logs and member lists.
  display_name String

  /// URL to the user's avatar image. Optional profile customization.
  avatar_uri String? @db.VarChar(80000)

  /// User's phone number. Optional contact information.
  phone_number String?

  /// Timestamp when the member account was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the member record was last updated.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when the member account was soft-deleted. NULL means active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // HAS RELATIONS
  //   - format: (propertyKey targetModel)
  //----
