    "timer is active (deleted_at NULL)",
    timer.deleted_at === null,
  );
  TestValidator.predicate(
    "timer has start_at timestamp",
    timer.start_at !== undefined,
  );
  TestValidator.equals(
    "timer description matches",
    timer.description,
    timerDescription,
  );
}

