export async function putHrmsMemberTimelogsTimelogId(props: {
  member: MemberPayload;
  timelogId: string & tags.Format<"uuid">;
  body: IHrmsTimelog.IUpdate;
}): Promise<IHrmsTimelog> {
  const timelog = await MyGlobal.prisma.hrms_timelogs.findUniqueOrThrow({
    where: { id: props.timelogId },
    select: {
      id: true,
      employee_id: true,
      project_id: true,
      task_id: true,
      billable: true,
      created_at: true,
      date: true,
      description: true,
      duration_minutes: true,
      updated_at: true,
      deleted_at: true,
      employee: { select: { id: true, organization_member_id: true } },
      project: { select: { id: true } },
      task: { select: { id: true } },
    },
  });
  if (timelog.deleted_at !== null) {
    throw new HttpException("Timelog is already deleted", 409);
  }
  const employee = timelog.employee;
  const employeeOrgMember =
    await MyGlobal.prisma.hrms_organization_members.findUnique({
      where: { id: employee.organization_member_id },
      select: {
        hrms_organization_id: true,
        organizationRole: { select: { permission: true } },
      },
    });
  if (employeeOrgMember === null) {
    throw new HttpException("Employee organization member not found", 409);
  }
  const memberOrgMember =
    await MyGlobal.prisma.hrms_organization_members.findFirst({
      where: {
        hrms_member_id: props.member.id,
        hrms_organization_id: employeeOrgMember.hrms_organization_id,
      },
      select: {
        organizationRole: { select: { permission: true } },
      },
    });
  const isOwner = employee.organization_member_id === props.member.id;
  const hasTimeManagePermission =
    (memberOrgMember !== null &&
      memberOrgMember.organizationRole?.permission === "time:manage") ??
    false;
  if (!isOwner && !hasTimeManagePermission) {
    throw new HttpException("Forbidden", 403);
  }
  if (props.body.duration_minutes !== undefined) {
    if (props.body.duration_minutes < 1) {
      throw new HttpException("Duration must be at least 1 minute", 400);
    }
  }
  if (props.body.project_id !== undefined) {
    const projectAssignment =
      await MyGlobal.prisma.hrms_project_members.findFirst({
        where: {
          employee_id: timelog.employee_id,
          project_id: props.body.project_id,
        },
      });
    if (projectAssignment === null) {
      throw new HttpException(
        "Employee is not assigned to the specified project",
        400,
      );
    }
  }
  if (props.body.task_id !== undefined && props.body.task_id !== null) {
    const task = await MyGlobal.prisma.hrms_tasks.findUnique({
      where: { id: props.body.task_id },
      select: { hrms_project_id: true },
    });
    if (task === null) {
      throw new HttpException("Task not found", 404);
    }
    const targetProjectId = props.body.project_id ?? timelog.project_id;
    if (task.hrms_project_id !== targetProjectId) {
      throw new HttpException(
        "Task does not belong to the specified project",
        400,
      );
    }
  }
  const updateData = {
    ...(props.body.date !== undefined && {
      date: new Date(props.body.date),
    }),
    ...(props.body.description !== undefined && {
      description: props.body.description,
    }),
    ...(props.body.duration_minutes !== undefined && {
      duration_minutes: props.body.duration_minutes,
    }),
    ...(props.body.project_id !== undefined && {
      project: {
        connect: { id: props.body.project_id },
      },
    }),
    ...(props.body.task_id !== undefined && {
      task:
        props.body.task_id === null
          ? { disconnect: true }
          : {
              connect: { id: props.body.task_id },
            },
    }),
    ...(props.body.billable !== undefined && {
      billable: props.body.billable,
    }),
    updated_at: new Date(),
  } satisfies Prisma.hrms_timelogsUpdateInput;
  const updated = await MyGlobal.prisma.hrms_timelogs.update({
    where: { id: props.timelogId },
    data: updateData,
    select: {
      id: true,
      employee_id: true,
      project_id: true,
      task_id: true,
      billable: true,
      created_at: true,
      date: true,
      description: true,
      duration_minutes: true,
      updated_at: true,
      deleted_at: true,
    },
  });
  return {
    id: updated.id,
    employee_id: updated.employee_id,
    project_id: updated.project_id,
    task_id: updated.task_id,
    billable: updated.billable,
    created_at: updated.created_at.toISOString(),
    date: updated.date.toISOString(),
    description: updated.description ?? undefined,
    duration_minutes: updated.duration_minutes,
    updated_at: updated.updated_at.toISOString(),
    deleted_at: updated.deleted_at?.toISOString() ?? null,
  } satisfies IHrmsTimelog;
}

import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { MemberPayload } from "../decorators/payload/MemberPayload";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function deleteHrmsMemberTimelogsTimelogId(props: {
  member: MemberPayload;
  timelogId: string & tags.Format<"uuid">;
}): Promise<void> {
  // Step 1: Find the timelog
  const timelog = await MyGlobal.prisma.hrms_timelogs.findUnique({
    where: { id: props.timelogId },
    select: {
      id: true,
      employee_id: true,
      date: true,
      deleted_at: true,
    },
  });
  if (timelog === null || timelog.deleted_at !== null) {
    throw new HttpException("Timelog not found", 404);
  }
  // Step 2: Get employee to check active status
  const employee = await MyGlobal.prisma.hrms_employees.findUnique({
    where: { id: timelog.employee_id },
    select: { id: true, status: true },
  });
  if (employee === null || employee.status !== "active") {
    throw new HttpException("Timelog not found", 404);
  }
  // Step 3: Check ownership
  const isOwner = timelog.employee_id === props.member.id;
  // Step 4: Check permission override if not owner
  if (!isOwner) {
    const organizationMember =
      await MyGlobal.prisma.hrms_organization_members.findFirst({
        where: {
          hrms_member_id: props.member.id,
          deleted_at: null,
        },
        select: {
          hrms_organization_role_id: true,
        },
      });
    if (organizationMember === null) {
      throw new HttpException("You're not enrolled", 403);
    }
    const role = await MyGlobal.prisma.hrms_organization_roles.findFirst({
      where: {
        id: organizationMember.hrms_organization_role_id,
      },
      select: {
        id: true,
      },
    });
    if (role === null) {
      throw new HttpException("Forbidden", 403);
    }
  }
  // Step 5: Check timesheet lock by finding timesheets for the employee that are submitted or approved
  // A timelog belongs to a timesheet if it was created during that timesheet's week
  const timesheets = await MyGlobal.prisma.hrms_timesheets.findMany({
    where: {
      hrms_employee_id: timelog.employee_id,
      status: { in: ["submitted", "approved"] },
    },
    select: {
      id: true,
      week_start_date: true,
      week_end_date: true,
    },
  });
  const timelogDateOnly = new Date(timelog.date);
  timelogDateOnly.setHours(0, 0, 0, 0);
  const hasTimelogInTimesheet = timesheets.some((ts) => {
    const tsStartDate = new Date(ts.week_start_date);
    tsStartDate.setHours(0, 0, 0, 0);
    const tsEndDate = new Date(ts.week_end_date);
    tsEndDate.setHours(23, 59, 59, 999);
    return timelogDateOnly >= tsStartDate && timelogDateOnly <= tsEndDate;
  });
  if (hasTimelogInTimesheet) {
    throw new HttpException(
      "Cannot delete timelog in submitted or approved timesheet",
      409,
    );
  }
  // Step 6: Soft delete
  await MyGlobal.prisma.hrms_timelogs.update({
    where: { id: props.timelogId },
    data: {
      deleted_at: new Date(),
    },
  });
  // Step 7: Return 204 No Content (void return type)
}

import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { MemberPayload } from "../decorators/payload/MemberPayload";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function deleteHrmsMemberTimesheetsTimesheetId(props: {
  member: MemberPayload;
  timesheetId: string & tags.Format<"uuid">;
}): Promise<void> {
  // Step 1: Query the timesheet to validate existence and status
  const timesheet = await MyGlobal.prisma.hrms_timesheets.findUniqueOrThrow({
    where: { id: props.timesheetId },
  });
  // Step 2: Validate timesheet status (only draft or rejected can be deleted)
  if (timesheet.status !== "draft" && timesheet.status !== "rejected") {
    throw new HttpException(
      "Timesheet cannot be deleted in submitted or approved status",
      403,
    );
  }
  // Step 3: Get member's organization membership to validate access and organization
  const membership = await MyGlobal.prisma.hrms_organization_members.findFirst({
    where: {
      hrms_member_id: props.member.id,
      deleted_at: null,
    },
    include: {
      organizationRole: {
        include: {
          permissions: true,
        },
      },
    },
  });
  if (!membership) {
    throw new HttpException("Member is not enrolled in any organization", 403);
  }
  // Step 4: Get the employee record associated with this organization membership
  const employee = await MyGlobal.prisma.hrms_employees.findFirst({
    where: {
      organization_member_id: membership.id,
      deleted_at: null,
    },
  });
  if (!employee) {
    throw new HttpException(
      "Employee record not found for this membership",
      403,
    );
  }
  // Step 5: Check if member owns the timesheet (via employee record)
  const isOwner = employee.id === timesheet.hrms_employee_id;
  // Step 6: Check if member has time:manage permission
  const hasTimeManagePermission = membership.organizationRole.permissions.some(
    (p) => p.permission === "time:manage",
  );
  // Step 7: Validate access (must be owner OR have permission)
  if (!isOwner && !hasTimeManagePermission) {
    throw new HttpException(
      "Forbidden: You do not have permission to delete this timesheet",
      403,
    );
  }
  // Step 8: Validate organization isolation
  // The timesheet's employee must belong to the same organization as the member
  if (employee.organization_member_id !== membership.id) {
    throw new HttpException(
      "Timesheet belongs to a different organization",
      403,
    );
  }
  // Step 9: Soft delete the timesheet
  await MyGlobal.prisma.hrms_timesheets.update({
    where: { id: props.timesheetId },
    data: {
      deleted_at: new Date(),
    },
  });
  // Step 10: Soft delete associated timelogs that fall within this timesheet's week
  // Timelogs are deleted if they belong to the same employee and date falls within the week range
  await MyGlobal.prisma.hrms_timelogs.updateMany({
    where: {
      employee_id: timesheet.hrms_employee_id,
      deleted_at: null,
      date: {
        gte: timesheet.week_start_date,
        lte: timesheet.week_end_date,
      },
    },
    data: {
      deleted_at: new Date(),
    },
  });
}

import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
