import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function patchHrmsMemberEmailVerifications(props: {
  member: MemberPayload;
  body: IHrmsMemberEmailVerification.IRequest;
}): Promise<IPageIHrmsMemberEmailVerification.ISummary> {
  const page = props.body.page ?? 1;
  const limit = Math.min(props.body.limit ?? 20, 100);
  const skip = (page - 1) * limit;
  const sort_by = props.body.sort_by ?? "created_at";
  const sort_order = props.body.sort_order ?? "desc";
  const whereConditions: Prisma.hrms_member_email_verificationsWhereInput = {
    deleted_at: null,
  };
  if (props.body.member_id !== undefined) {
    whereConditions.member_id = props.body.member_id;
  }
  if (props.body.created_at_from !== undefined) {
    if (props.body.created_at_to !== undefined) {
      whereConditions.created_at = {
        gte: new Date(props.body.created_at_from),
        lte: new Date(props.body.created_at_to),
      };
    } else {
      whereConditions.created_at = {
        gte: new Date(props.body.created_at_from),
      };
    }
  } else if (props.body.created_at_to !== undefined) {
    whereConditions.created_at = {
      lte: new Date(props.body.created_at_to),
    };
  }
  if (props.body.expires_at_from !== undefined) {
    if (props.body.expires_at_to !== undefined) {
      whereConditions.expires_at = {
        gte: new Date(props.body.expires_at_from),
        lte: new Date(props.body.expires_at_to),
      };
    } else {
      whereConditions.expires_at = {
        gte: new Date(props.body.expires_at_from),
      };
    }
  } else if (props.body.expires_at_to !== undefined) {
    whereConditions.expires_at = {
      lte: new Date(props.body.expires_at_to),
    };
  }
  if (props.body.status !== undefined) {
    const now = new Date();
    switch (props.body.status) {
      case "active":
        whereConditions.deleted_at = null;
        whereConditions.used_at = null;
        whereConditions.expires_at = { gt: now };
        break;
      case "used":
        whereConditions.OR = [
          { deleted_at: { not: null } },
          { used_at: { not: null } },
        ];
        break;
      case "expired":
        whereConditions.OR = [
          { expires_at: { lte: now } },
          { deleted_at: { not: null } },
        ];
        break;
    }
  }
  const orderByInput = {
    [sort_by]: sort_order,
  } satisfies Prisma.hrms_member_email_verificationsOrderByWithRelationInput;
  const data = await MyGlobal.prisma.hrms_member_email_verifications.findMany({
    where: whereConditions,
    skip,
    take: limit,
    orderBy: orderByInput,
    include: {
      member: {
        select: {
          email: true,
          display_name: true,
        },
      },
    },
  });
  const total = await MyGlobal.prisma.hrms_member_email_verifications.count({
    where: whereConditions,
  });
  const transformedData = data.map((record) => {
    const now = new Date();
    let status: "active" | "used" | "expired";
    if (record.used_at !== null) {
      status = "used";
    } else if (record.deleted_at !== null) {
      status = "used";
    } else if (record.expires_at <= now) {
      status = "expired";
    } else {
      status = "active";
    }
    return {
      id: record.id,
      expires_at: toISOStringSafe(record.expires_at),
      used_at: record.used_at !== null ? toISOStringSafe(record.used_at) : null,
      created_at: toISOStringSafe(record.created_at),
      member_email: record.member.email,
      member_display_name: record.member.display_name,
      status,
    } satisfies IHrmsMemberEmailVerification.ISummary;
  });
  return {
    data: transformedData,
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.ceil(total / limit),
    } satisfies IPage.IPagination,
  } satisfies IPageIHrmsMemberEmailVerification.ISummary;
}

import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { IHrmsProjectMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IHrmsProjectMember";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { IPageIHrmsProjectMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIHrmsProjectMember";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { MemberPayload } from "../decorators/payload/MemberPayload";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function patchHrmsMemberProjectsProjectIdMembers(props: {
  member: MemberPayload;
  projectId: string & tags.Format<"uuid">;
  body: IHrmsProjectMember.IRequest;
}): Promise<IPageIHrmsProjectMember.ISummary> {
  // Validate project exists
  const project = await MyGlobal.prisma.hrms_projects.findUniqueOrThrow({
    where: { id: props.projectId, deleted_at: null },
  });
  // Get user's organization membership
  const userMember = await MyGlobal.prisma.hrms_organization_members.findFirst({
    where: {
      hrms_member_id: props.member.id,
      hrms_organization_id: project.hrms_organization_id,
      deleted_at: null,
    },
    include: {
      organizationRole: true,
    },
  });
  if (!userMember) {
    throw new HttpException("Forbidden", 403);
  }
  // Pagination params
  const page = props.body.page ?? 1;
  const limit = props.body.limit ?? 100;
  const skip = (page - 1) * limit;
  // Build where clause
  const whereClause: Prisma.hrms_project_membersWhereInput = {
    project_id: props.projectId,
    deleted_at: null,
  };
  // Filter by status based on includeInactive
  if (props.body.includeInactive === true) {
    // Include all statuses
  } else {
    whereClause.status = "active";
  }
  // Get total count
  const total = await MyGlobal.prisma.hrms_project_members.count({
    where: whereClause,
  });
  // Get members with employee details
  const data = await MyGlobal.prisma.hrms_project_members.findMany({
    where: whereClause,
    skip,
    take: limit,
    orderBy: { created_at: "desc" },
    include: {
      employee: {
        include: {
          department: true,
        },
      },
    },
  });
  // If timelog metrics are requested, we need to aggregate
  const metric = props.body.metric ?? "total";
  let transformedData: IHrmsProjectMember.ISummary[] = [];
  if (
    metric === "total" ||
    metric === "billable" ||
    metric === "billable_rate"
  ) {
    // Aggregate timelog data for each employee
    transformedData = await Promise.all(
      data.map(async (pm) => {
        const employee = pm.employee;
        const departmentName = employee.department?.name ?? "";
        // Query timelog metrics for this employee, optionally filtered by projectIds and date range
        const timelogMetrics = await MyGlobal.prisma.hrms_timelogs.groupBy({
          by: ["employee_id"],
          where: {
            employee_id: employee.id,
            ...(props.body.startDate && {
              date: {
                gte: new Date(props.body.startDate),
              },
            }),
            ...(props.body.endDate && {
              date: {
                lte: new Date(props.body.endDate),
              },
            }),
            ...(props.body.projectIds &&
              props.body.projectIds.length > 0 && {
                project_id: {
                  in: props.body.projectIds,
                },
              }),
          },
          _sum: {
            duration_minutes: true,
            ...(props.body.projectIds &&
              props.body.projectIds.length > 0 && {
                duration_minutes: true,
              }),
          },
        });
        const employeeTimelog = timelogMetrics.find(
          (t) => t.employee_id === employee.id,
        );
        const totalMinutes = employeeTimelog?._sum.duration_minutes ?? 0;
        const totalHours = totalMinutes / 60;
        // Billable hours
        const billableTimelogs = await MyGlobal.prisma.hrms_timelogs.aggregate({
          where: {
            employee_id: employee.id,
            billable: true,
            ...(props.body.startDate && {
              date: {
                gte: new Date(props.body.startDate),
              },
            }),
            ...(props.body.endDate && {
              date: {
                lte: new Date(props.body.endDate),
              },
            }),
            ...(props.body.projectIds &&
              props.body.projectIds.length > 0 && {
                project_id: {
                  in: props.body.projectIds,
                },
              }),
          },
          _sum: {
            duration_minutes: true,
          },
        });
        const billableMinutes = billableTimelogs._sum.duration_minutes ?? 0;
        const billableHours = billableMinutes / 60;
        const billableRate = totalHours > 0 ? billableHours / totalHours : 0;
        // Hours by project if filtered
        const hoursByProject: IHrmsProjectMember.IHoursByProject[] | undefined =
          props.body.projectIds && props.body.projectIds.length > 0
            ? await ArrayUtil.asyncMap(
                await MyGlobal.prisma.hrms_timelogs.groupBy({
                  by: ["project_id"],
                  where: {
                    employee_id: employee.id,
                    ...(props.body.startDate && {
                      date: {
                        gte: new Date(props.body.startDate),
                      },
                    }),
                    ...(props.body.endDate && {
                      date: {
                        lte: new Date(props.body.endDate),
                      },
                    }),
                    project_id: {
                      in: props.body.projectIds,
                    },
                  },
                  _sum: {
                    duration_minutes: true,
                  },
                }),
                async (t) => {
                  const projectRecord =
                    await MyGlobal.prisma.hrms_projects.findUnique({
                      where: { id: t.project_id },
                      select: { name: true },
                    });
                  return {
                    projectName: projectRecord?.name ?? "Unknown",
                    totalHours: (t._sum.duration_minutes ?? 0) / 60,
                    billableHours: 0, // Would need separate billable aggregation per project
                  } satisfies IHrmsProjectMember.IHoursByProject;
                },
              )
            : undefined;
        return {
          id: employee.id as string & tags.Format<"uuid">,
          displayName: employee.display_name,
          departmentName: departmentName,
          totalHours: totalHours,
          billableHours: billableHours,
          billableRate: billableRate,
          projectName:
            props.body.projectIds && props.body.projectIds.length > 0
              ? undefined
              : project.name,
          hoursByProject: hoursByProject,
        } satisfies IHrmsProjectMember.ISummary;
      }),
    );
  } else {
    // No metrics - simple mapping
    transformedData = data.map((pm) => {
      const employee = pm.employee;
      return {
        id: employee.id as string & tags.Format<"uuid">,
        displayName: employee.display_name,
        departmentName: employee.department?.name ?? "",
        totalHours: 0,
        billableHours: 0,
        billableRate: 0,
        projectName: project.name,
        hoursByProject: undefined,
      } satisfies IHrmsProjectMember.ISummary;
    });
  }
  return {
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.ceil(total / limit),
    } satisfies IPage.IPagination,
    data: transformedData,
  } satisfies IPageIHrmsProjectMember.ISummary;
}

import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { IHrmsTask } from "@ORGANIZATION/PROJECT-api/lib/structures/IHrmsTask";
import { IHrmsTaskAnalyticGrouping } from "@ORGANIZATION/PROJECT-api/lib/structures/IHrmsTaskAnalyticGrouping";
import { IHrmsTaskParentTaskFilter } from "@ORGANIZATION/PROJECT-api/lib/structures/IHrmsTaskParentTaskFilter";
import { IHrmsTaskPriority } from "@ORGANIZATION/PROJECT-api/lib/structures/IHrmsTaskPriority";
import { IHrmsTaskStatusHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IHrmsTaskStatusHistory";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { IPageIHrmsTask } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIHrmsTask";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { MemberPayload } from "../decorators/payload/MemberPayload";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function patchHrmsMemberProjectsProjectIdTasks(props: {
  member: MemberPayload;
  projectId: string & tags.Format<"uuid">;
  body: IHrmsTask.IRequest;
}): Promise<IPageIHrmsTask.ISummary> {
  // Fetch project with validation
  const project = await MyGlobal.prisma.hrms_projects.findUniqueOrThrow({
    where: {
      id: props.projectId,
      deleted_at: null,
    },
    select: {
      id: true,
      name: true,
      hrms_organization_id: true,
    },
  });
  // Build WHERE clause for task query
  const whereInput: Prisma.hrms_tasksWhereInput = {
    hrms_project_id: props.projectId,
    deleted_at: null,
    ...(props.body.status &&
      props.body.status.length > 0 && {
        status: { in: props.body.status },
      }),
    ...(props.body.priority &&
      props.body.priority.length > 0 && {
        priority: { in: props.body.priority },
      }),
    ...(props.body.employeeIds &&
      props.body.employeeIds.length > 0 && {
        hrms_employee_id: { in: props.body.employeeIds },
      }),
    ...(props.body.withAssignment !== undefined && {
      hrms_employee_id: props.body.withAssignment ? { not: null } : null,
    }),
    ...(props.body.parentTaskFilter === "parent" && {
      hrms_task_id: null,
    }),
    ...(props.body.parentTaskFilter === "subtask" && {
      hrms_task_id: { not: null },
    }),
    ...(props.body.dueDateFrom && {
      due_date: { gte: new Date(props.body.dueDateFrom) },
    }),
    ...(props.body.dueDateTo && {
      due_date: { lte: new Date(props.body.dueDateTo) },
    }),
    ...(props.body.createdDateFrom && {
      created_at: { gte: new Date(props.body.createdDateFrom) },
    }),
    ...(props.body.createdDateTo && {
      created_at: { lte: new Date(props.body.createdDateTo) },
    }),
  } satisfies Prisma.hrms_tasksWhereInput;
  // Pagination parameters
  const page = props.body.page ?? 1;
  const limit = props.body.limit ?? 20;
  const skip = (page - 1) * limit;
  // Query tasks
  const tasks = await MyGlobal.prisma.hrms_tasks.findMany({
    where: whereInput,
    skip,
    take: limit,
    orderBy: { created_at: "desc" },
  });
  // Get total count for pagination
  const total = await MyGlobal.prisma.hrms_tasks.count({
    where: whereInput,
  });
  // Build response data - map tasks to IHrmsTask.ISummary format
  const data = tasks.map((task) => ({
    project_id: task.hrms_project_id,
    project_name: project.name,
    task_count: 1,
  }));
  // Calculate pagination metadata
  const pages = Math.ceil(total / limit);
  return {
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages,
    },
    data: data,
  } satisfies IPageIHrmsTask.ISummary;
}

import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { IHrmsTopEmployee } from "@ORGANIZATION/PROJECT-api/lib/structures/IHrmsTopEmployee";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { IPageIHrmsTopEmployee } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIHrmsTopEmployee";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { MemberPayload } from "../decorators/payload/MemberPayload";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function patchHrmsMemberReportsTopEmployees(props: {
  member: MemberPayload;
  body: IHrmsTopEmployee.IRequest;
}): Promise<IPageIHrmsTopEmployee.ISummary> {
  const page = props.body.page ?? 1;
  const limit = props.body.limit ?? 100;
  const skip = (page - 1) * limit;
  // Validate date range if provided
  if (props.body.dateRange?.startDate && props.body.dateRange?.endDate) {
    if (props.body.dateRange.startDate > props.body.dateRange.endDate) {
      throw new HttpException(
        "start_date must be before or equal to end_date",
        400,
      );
    }
  }
  // Use default to current week if not specified
  const now = new Date();
  const endOfWeek = new Date(now);
  const startOfWeek = new Date(endOfWeek);
  startOfWeek.setDate(endOfWeek.getDate() - 6);
  const effectiveStartDate =
    props.body.dateRange?.startDate || startOfWeek.toISOString().split("T")[0];
  const effectiveEndDate =
    props.body.dateRange?.endDate || endOfWeek.toISOString().split("T")[0];
  // Build WHERE clause for timelogs
  const timelogWhere: Prisma.hrms_timelogsWhereInput = {
    date: {
      gte: new Date(`${effectiveStartDate}T00:00:00.000Z`),
      lte: new Date(`${effectiveEndDate}T23:59:59.999Z`),
    },
    deleted_at: null,
    ...(props.body.employeeId && { employee_id: props.body.employeeId }),
    ...(props.body.projectId && { project_id: props.body.projectId }),
  };
  // Aggregate timelog data by employee with conditional billable sum
  const timelogAggregations = await MyGlobal.prisma.hrms_timelogs.groupBy({
    by: ["employee_id"],
    where: timelogWhere,
    _sum: {
      duration_minutes: true,
    },
    _count: {
      project_id: true,
      task_id: true,
    },
  });
  // Calculate billable hours using additional query
  const billableTimelogAggregations =
    await MyGlobal.prisma.hrms_timelogs.groupBy({
      by: ["employee_id"],
      where: {
        ...timelogWhere,
        billable: true,
      },
      _sum: {
        duration_minutes: true,
      },
    });
  // Build maps for aggregation data
  const totalHoursMap = new Map<string, number>();
  const billableHoursMap = new Map<string, number>();
  const projectCountMap = new Map<string, number>();
  const taskCountMap = new Map<string, number>();
  for (const agg of timelogAggregations) {
    totalHoursMap.set(agg.employee_id, agg._sum.duration_minutes ?? 0);
    projectCountMap.set(agg.employee_id, agg._count.project_id);
    taskCountMap.set(agg.employee_id, agg._count.task_id);
  }
  for (const agg of billableTimelogAggregations) {
    billableHoursMap.set(agg.employee_id, agg._sum.duration_minutes ?? 0);
  }
  // Get employee IDs from aggregations
  const employeeIds = Array.from(totalHoursMap.keys());
  if (employeeIds.length === 0) {
    return {
      pagination: {
        current: page,
        limit,
        records: 0,
        pages: 0,
      } satisfies IPage.IPagination,
      data: [],
    };
  }
  // Build employee WHERE clause (active only)
  const employeeWhere: Prisma.hrms_employeesWhereInput = {
    id: { in: employeeIds },
    status: "active",
    deleted_at: null,
  };
  // Get employee details with aggregation data
  const employeesWithAggregation =
    await MyGlobal.prisma.hrms_employees.findMany({
      where: employeeWhere,
      select: {
        id: true,
        display_name: true,
        position: true,
        department_id: true,
      },
    });
  // Build data with aggregation
  const data: IHrmsTopEmployee.ISummary[] = [];
  for (const employee of employeesWithAggregation) {
    const totalHours = totalHoursMap.get(employee.id) || 0;
    const billableHours = billableHoursMap.get(employee.id) || 0;
    const projectCount = projectCountMap.get(employee.id) || 0;
    const taskCount = taskCountMap.get(employee.id) || 0;
    data.push({
      id: employee.id as string & tags.Format<"uuid">,
      display_name: employee.display_name,
      position: employee.position ?? "",
      department_id: employee.department_id,
      total_hours: totalHours,
      billable_hours: billableHours,
      project_count: projectCount,
      task_count: taskCount,
    });
  }
  // Apply sorting
  const sortField = props.body.sort ?? "total_hours";
  data.sort((a, b) => {
    switch (sortField) {
      case "total_hours":
        return b.total_hours - a.total_hours;
      case "billable_hours":
        return b.billable_hours - a.billable_hours;
      case "project_count":
        return b.project_count - a.project_count;
      case "task_count":
        return b.task_count - a.task_count;
      case "employee_name":
        return a.display_name.localeCompare(b.display_name);
      case "department":
        if (a.department_id && b.department_id) {
          return a.department_id.localeCompare(b.department_id);
        } else if (a.department_id) {
          return -1;
        } else if (b.department_id) {
          return 1;
        }
        return 0;
      default:
        return b.total_hours - a.total_hours;
    }
  });
  // Apply pagination
  const paginatedData = data.slice(skip, skip + limit);
  // Count total
  const total = data.length;
  return {
    pagination: {
      current: page,
      limit,
      records: total,
      pages: Math.ceil(total / limit),
    } satisfies IPage.IPagination,
    data: paginatedData,
  };
}

