    updated_at: project?.updated_at
      ? toISOStringSafe(project.updated_at)
      : toISOStringSafe(new Date("9999-12-31T23:59:59.999Z")),
  };
  const projectsWithHighUtilization: IHrmsProject.ISummary[] = [];
  return {
