import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function getHrmsMemberProjectsDashboard(props: {
  member: MemberPayload;
}): Promise<IHrmsProject> {
  const memberMembership =
    await MyGlobal.prisma.hrms_organization_members.findFirst({
      where: {
        hrms_member_id: props.member.id,
        deleted_at: null,
      },
      include: {
        employees: {
          where: {
            deleted_at: null,
          },
          take: 1,
        },
        organization: {
          select: {
            id: true,
            name: true,
          },
        },
      },
    });
  if (!memberMembership || memberMembership.employees.length === 0) {
    throw new HttpException("Employee record not found", 404);
  }
  const employee = memberMembership.employees[0];
  const projectMemberships =
    await MyGlobal.prisma.hrms_project_members.findMany({
      where: {
        employee_id: employee.id,
        status: "active",
        deleted_at: null,
      },
      include: {
        project: true,
      },
      orderBy: {
        created_at: "desc",
      },
    });
  const projectIds = projectMemberships
    .map((m) => m.project.id)
    .filter((id): id is string => id !== undefined);
  const projects = await MyGlobal.prisma.hrms_projects.findMany({
    where: {
      id: {
        in: projectIds,
      },
      deleted_at: null,
    },
    select: {
      id: true,
      name: true,
      description: true,
      color_code: true,
      hrms_organization_id: true,
      status: true,
      budget_hours: true,
      start_date: true,
      end_date: true,
      created_at: true,
      updated_at: true,
    },
  });
  const projectMap = new Map(projects.map((p) => [p.id, p]));
  const organizationsSet = new Set(
    projectMemberships
      .map((m) => m.project.hrms_organization_id)
      .filter((id): id is string => id !== undefined),
  );
  const organizationData = await MyGlobal.prisma.hrms_organizations.findMany({
    where: {
      id: {
        in: Array.from(organizationsSet),
      },
    },
    select: {
      id: true,
      name: true,
    },
  });
  const organizationByName = new Map(
    organizationData.map((org) => [org.id, org.name]),
  );
  const projectsSummary: IHrmsProject.ISummary[] = await ArrayUtil.asyncMap(
    projectMemberships,
    async (membership) => {
      const project = projectMap.get(membership.project.id);
      if (!project) {
        return null!;
      }
      const [allTimelogs, allTasks] = await Promise.all([
        MyGlobal.prisma.hrms_timelogs.findMany({
          where: {
            project_id: project.id,
            employee_id: employee.id,
            deleted_at: null,
          },
        }),
        MyGlobal.prisma.hrms_tasks.findMany({
          where: {
            hrms_project_id: project.id,
            deleted_at: null,
          },
        }),
      ]);
      const totalMinutes = allTimelogs.reduce(
        (sum, t) => sum + (t.duration_minutes || 0),
        0,
      );
      const actualHours = totalMinutes / 60;
      let budgetUtilizationPercentage: number | null = null;
      if (project.budget_hours !== null && project.budget_hours > 0) {
        budgetUtilizationPercentage = Number(
          ((actualHours / project.budget_hours) * 100).toFixed(1),
        );
      }
      const taskCounts = allTasks.reduce(
        (
          acc,
          task: {
            status: string;
          },
        ) => {
          acc.total_tasks++;
          if (task.status === "open" || task.status === "pending") {
            acc.pending_tasks++;
          } else if (task.status === "in-progress") {
            acc.in_progress_tasks++;
          } else if (task.status === "completed") {
            acc.completed_tasks++;
          } else if (task.status === "closed") {
            acc.closed_tasks++;
          }
          return acc;
        },
        {
          total_tasks: 0,
          pending_tasks: 0,
          in_progress_tasks: 0,
          completed_tasks: 0,
          closed_tasks: 0,
        },
      );
      const timelogCount = allTimelogs.length;
      const organizationName =
        organizationByName.get(project.hrms_organization_id) ?? "";
      return {
        id: project.id as string & tags.Format<"uuid">,
        name: project.name,
        description: project.description ?? "",
        color_code: project.color_code,
        organization_id: project.hrms_organization_id as string &
          tags.Format<"uuid">,
        organization_name: organizationName,
        status: project.status as "active" | "completed" | "archived",
        budget_hours: project.budget_hours,
        start_date:
          project.start_date !== null && project.start_date !== undefined
            ? toISOStringSafe(project.start_date)
            : null,
        end_date:
          project.end_date !== null && project.end_date !== undefined
            ? toISOStringSafe(project.end_date)
            : null,
        planned_hours: project.budget_hours || 0,
        actual_hours: actualHours,
        budget_utilization_percentage: budgetUtilizationPercentage,
        total_tasks: taskCounts.total_tasks as number & tags.Type<"int32">,
        pending_tasks: taskCounts.pending_tasks as number & tags.Type<"int32">,
        in_progress_tasks: taskCounts.in_progress_tasks as number &
          tags.Type<"int32">,
        completed_tasks: taskCounts.completed_tasks as number &
          tags.Type<"int32">,
        closed_tasks: taskCounts.closed_tasks as number & tags.Type<"int32">,
        timelog_count: timelogCount as number & tags.Type<"int32">,
        created_at:
          project.created_at !== null && project.created_at !== undefined
            ? toISOStringSafe(project.created_at)
            : toISOStringSafe(new Date()),
        updated_at:
          project.updated_at !== null && project.updated_at !== undefined
            ? toISOStringSafe(project.updated_at)
            : toISOStringSafe(new Date()),
      } satisfies IHrmsProject.ISummary;
    },
  );
  return {
    dashboard_type: "personal" as const,
    generation_timestamp: toISOStringSafe(new Date()),
    hours_today: undefined,
    hours_this_week: undefined,
    active_timer: undefined,
    recent_timelogs: undefined,
    pending_timesheets_count: undefined,
    assigned_tasks: undefined,
    active_employee_count: undefined,
    total_hours_this_week: undefined,
    budget_alerts: projectsSummary.filter(
      (p) =>
        p.budget_utilization_percentage !== null &&
        p.budget_utilization_percentage! > 80,
    ),
    top_employees: undefined,
  } satisfies IHrmsProject;
}

import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { IHrmsEmployee } from "@ORGANIZATION/PROJECT-api/lib/structures/IHrmsEmployee";
import { IHrmsEmployeeContract } from "@ORGANIZATION/PROJECT-api/lib/structures/IHrmsEmployeeContract";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { IPageIHrmsEmployeeContract } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIHrmsEmployeeContract";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { MemberPayload } from "../decorators/payload/MemberPayload";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function patchHrmsMemberContractsAnalytics(props: {
  member: MemberPayload;
  body: IHrmsEmployeeContract.IRequest;
}): Promise<IPageIHrmsEmployeeContract.ISummary> {
  // Extract pagination with defaults
  const page = props.body.page ?? 1;
  const limit = props.body.limit ?? 20;
  const skip = (page - 1) * limit;
  // Validate date range if both provided
  if (props.body.start_date && props.body.end_date) {
    const startDate = new Date(props.body.start_date);
    const endDate = new Date(props.body.end_date);
    if (startDate >= endDate) {
      throw new HttpException("Start date must be before end date", 400);
    }
  }
  // Get organization context from member
  const organizationMembership =
    await MyGlobal.prisma.hrms_organization_members.findFirst({
      where: {
        hrms_member_id: props.member.id,
        deleted_at: null,
      },
      select: {
        hrms_organization_id: true,
      },
    });
  if (!organizationMembership) {
    throw new HttpException("Organization context not found", 404);
  }
  const organizationId = organizationMembership.hrms_organization_id;
  // Build base filter criteria
  const baseFilter: Prisma.hrms_employee_contractsWhereInput = {
    hrms_employee: {
      organizationMember: {
        hrms_organization_id: organizationId,
        deleted_at: null,
      },
    },
    deleted_at: null,
    ...(props.body.start_date && {
      start_date: {
        gte: new Date(props.body.start_date),
      },
    }),
    ...(props.body.end_date && {
      end_date: {
        lte: new Date(props.body.end_date),
      },
    }),
    ...(props.body.pay_period && {
      pay_period: props.body.pay_period,
    }),
    ...(props.body.department_id && {
      hrms_employee: {
        department_id: props.body.department_id,
      },
    }),
  };
  // Get total count
  const total = await MyGlobal.prisma.hrms_employee_contracts.count({
    where: baseFilter,
  });
  // Build aggregation queries for each pay_period
  const payPeriods: Array<"hourly" | "daily" | "weekly" | "monthly"> = [
    "hourly",
    "daily",
    "weekly",
    "monthly",
  ];
  const analyticsData: IHrmsEmployeeContract.ISummary[] = [];
  for (const payPeriod of payPeriods) {
    const periodFilter: Prisma.hrms_employee_contractsWhereInput = {
      ...baseFilter,
      pay_period: payPeriod,
    };
    // Get contracts for this pay period to calculate aggregations
    const contracts = await MyGlobal.prisma.hrms_employee_contracts.findMany({
      where: periodFilter,
      select: {
        id: true,
        start_date: true,
        end_date: true,
        pay_rate: true,
        hrms_employee_id: true,
      },
      skip,
      take: limit,
      orderBy: {
        start_date: "desc",
      },
    });
    if (contracts.length === 0) {
      continue;
    }
    // Calculate active contract count
    const activeContracts = await MyGlobal.prisma.hrms_employee_contracts.count(
      {
        where: {
          ...periodFilter,
          OR: [{ end_date: null }, { end_date: { gt: new Date() } }],
        },
      },
    );
    // Calculate pay rate statistics
    const payRates = contracts.map((c) => c.pay_rate);
    const avgPayRate =
      payRates.length > 0
        ? payRates.reduce((a, b) => a + b, 0) / payRates.length
        : 0;
    const minPayRate = payRates.length > 0 ? Math.min(...payRates) : 0;
    const maxPayRate = payRates.length > 0 ? Math.max(...payRates) : 0;
    // Calculate duration statistics
    const durations = contracts.map((c) => {
      const endDate = c.end_date ?? new Date();
      const startDate = c.start_date;
      const diffMs = endDate.getTime() - startDate.getTime();
      return Math.floor(diffMs / (1000 * 60 * 60 * 24));
    });
    const avgDuration =
      durations.length > 0
        ? durations.reduce((a, b) => a + b, 0) / durations.length
        : 0;
    const minDuration = durations.length > 0 ? Math.min(...durations) : 0;
    const maxDuration = durations.length > 0 ? Math.max(...durations) : 0;
    // Get employee data separately using hrms_employee_id
    const firstContract = contracts[0];
    const employee = firstContract
      ? await MyGlobal.prisma.hrms_employees.findUnique({
          where: { id: firstContract.hrms_employee_id },
          select: {
            id: true,
            display_name: true,
            position: true,
            department_id: true,
            status: true,
          },
        })
      : null;
    const employeeSummary: IHrmsEmployee.ISummary = {
      id:
        (employee?.id as string & tags.Format<"uuid">) ??
        "00000000-0000-0000-0000-000000000000",
      display_name: employee?.display_name ?? "Unknown",
      position: employee?.position ?? undefined,
      department_id: (employee?.department_id ??
        "00000000-0000-0000-0000-000000000000") as string & tags.Format<"uuid">,
      total_hours_logged: 0,
      timelog_count: 0,
      timesheets_submitted: 0,
      timesheets_approved: 0,
      timesheets_pending: 0,
      status: employee?.status ?? "unknown",
    };
    analyticsData.push({
      id: v4() as string & tags.Format<"uuid">,
      organization_context: organizationId as string & tags.Format<"uuid">,
      employee: employeeSummary,
      contract_count: contracts.length as number &
        tags.Type<"int32"> &
        tags.Minimum<0>,
      active_contract_count: activeContracts as number &
        tags.Type<"int32"> &
        tags.Minimum<0>,
      avg_pay_rate: avgPayRate,
      min_pay_rate: minPayRate,
      max_pay_rate: maxPayRate,
      avg_duration_days: avgDuration,
      min_duration_days: minDuration as number &
        tags.Type<"int32"> &
        tags.Minimum<0>,
      max_duration_days: maxDuration as number &
        tags.Type<"int32"> &
        tags.Minimum<0>,
      pay_period: payPeriod,
      created_at: toISOStringSafe(new Date()) as string &
        tags.Format<"date-time">,
    } satisfies IHrmsEmployeeContract.ISummary);
  }
  // Apply sorting if specified
  if (props.body.sort) {
    const sortField = props.body.sort;
    analyticsData.sort((a, b) => {
      switch (sortField) {
        case "start_date":
          return a.avg_duration_days - b.avg_duration_days;
        case "end_date":
          return b.avg_duration_days - a.avg_duration_days;
        case "pay_rate":
          return a.avg_pay_rate - b.avg_pay_rate;
        case "pay_period":
          return a.pay_period.localeCompare(b.pay_period);
        case "working_hours_per_week":
          return 0; // Not available in summary, default to 0
        default:
          return 0;
      }
    });
  }
  // Apply pagination to analytics data
  const paginatedData = analyticsData.slice(skip, skip + limit);
  return {
    data: paginatedData as IHrmsEmployeeContract.ISummary[],
    pagination: {
      current: page as number & tags.Type<"int32"> & tags.Minimum<0>,
      limit: limit as number & tags.Type<"int32"> & tags.Minimum<0>,
      records: total as number & tags.Type<"int32"> & tags.Minimum<0>,
      pages: Math.ceil(total / limit) as number &
        tags.Type<"int32"> &
        tags.Minimum<0>,
    } satisfies IPage.IPagination,
  } satisfies IPageIHrmsEmployeeContract.ISummary;
}

import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { IHrmsDepartment } from "@ORGANIZATION/PROJECT-api/lib/structures/IHrmsDepartment";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { IPageIHrmsDepartment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIHrmsDepartment";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { MemberPayload } from "../decorators/payload/MemberPayload";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function patchHrmsMemberOrganizationsOrganizationIdDepartments(props: {
  member: MemberPayload;
  organizationId: string & tags.Format<"uuid">;
  body: IHrmsDepartment.IRequest;
}): Promise<IPageIHrmsDepartment.ISummary> {
  // Parse pagination parameters
  const page =
    props.body.page !== undefined ? parseInt(props.body.page, 10) : 1;
  const limit = props.body.limit ?? 100;
  const skip = (page - 1) * limit;
  // Validate organization exists
  const organization = await MyGlobal.prisma.hrms_organizations.findUnique({
    where: { id: props.organizationId },
  });
  if (organization === null) {
    throw new HttpException("Organization not found", 404);
  }
  // Build WHERE clause
  const whereInput: Prisma.hrms_departmentsWhereInput = {
    organization_id: props.organizationId,
  };
  // Include/exclude soft-deleted based on flag
  if (props.body.include_deleted === false) {
    whereInput.deleted_at = null;
  }
  // Validate and apply parent_id filter if provided
  if (props.body.parent_id !== undefined) {
    const parentDepartment = await MyGlobal.prisma.hrms_departments.findUnique({
      where: { id: props.body.parent_id },
      select: { organization_id: true, deleted_at: true },
    });
    if (parentDepartment === null) {
      throw new HttpException("Parent department not found", 404);
    }
    if (parentDepartment.organization_id !== props.organizationId) {
      throw new HttpException(
        "Parent department does not belong to organization",
        400,
      );
    }
    whereInput.parent_id = props.body.parent_id;
  }
  // Apply name search filter using GIN index for trigram similarity
  if (props.body.search !== undefined) {
    whereInput.name = {
      contains: props.body.search,
      mode: "insensitive",
    } satisfies Prisma.StringFilter<string>;
  }
  // Build ORDER BY clause
  const orderByInput: Prisma.hrms_departmentsOrderByWithRelationInput =
    props.body.sort_by === "name"
      ? {
          name: props.body.sort_order === "asc" ? "asc" : "desc",
        }
      : props.body.sort_by === "created_at"
        ? {
            created_at: props.body.sort_order === "asc" ? "asc" : "desc",
          }
        : props.body.sort_by === "updated_at"
          ? {
              updated_at: props.body.sort_order === "asc" ? "asc" : "desc",
            }
          : ({
              created_at: "desc",
            } satisfies Prisma.hrms_departmentsOrderByWithRelationInput);
  // Fetch departments with parent relation
  const departments = await MyGlobal.prisma.hrms_departments.findMany({
    where: whereInput,
    skip,
    take: limit,
    orderBy: orderByInput,
    select: {
      id: true,
      name: true,
      description: true,
      parent_id: true,
      created_at: true,
      updated_at: true,
      deleted_at: true,
      organization_id: true,
      parent: {
        select: {
          id: true,
          name: true,
          description: true,
          created_at: true,
          updated_at: true,
          deleted_at: true,
          organization_id: true,
        },
      },
    },
  });
  // Get total count
  const total = await MyGlobal.prisma.hrms_departments.count({
    where: whereInput,
  });
  // Transform to ISummary format
  const data: IHrmsDepartment.ISummary[] = await ArrayUtil.asyncMap(
    departments,
    async (dept) => {
      const parentSummary: IHrmsDepartment.ISummary | null =
        dept.parent !== null
          ? ({
              id: dept.parent.id,
              name: dept.parent.name,
              description: dept.parent.description,
              parent: null,
              created_at: toISOStringSafe(dept.parent.created_at),
              updated_at: toISOStringSafe(dept.parent.updated_at),
              deleted_at:
                dept.parent.deleted_at !== null
                  ? toISOStringSafe(dept.parent.deleted_at)
                  : null,
              organization_id: dept.parent.organization_id,
            } satisfies IHrmsDepartment.ISummary)
          : null;
      return {
        id: dept.id,
        name: dept.name,
        description: dept.description,
        parent: parentSummary,
        created_at: toISOStringSafe(dept.created_at),
        updated_at: toISOStringSafe(dept.updated_at),
        deleted_at:
          dept.deleted_at !== null ? toISOStringSafe(dept.deleted_at) : null,
        organization_id: dept.organization_id,
      } satisfies IHrmsDepartment.ISummary;
    },
  );
  // Build pagination metadata
  const pagination: IPage.IPagination = {
    current: page,
    limit: limit,
    records: total,
    pages: Math.ceil(total / limit),
  } satisfies IPage.IPagination;
  return {
    pagination,
    data,
  } satisfies IPageIHrmsDepartment.ISummary;
}

import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { IHrmsTimelog } from "@ORGANIZATION/PROJECT-api/lib/structures/IHrmsTimelog";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { IPageIHrmsTimelog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIHrmsTimelog";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { MemberPayload } from "../decorators/payload/MemberPayload";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function patchHrmsMemberReportsTime(props: {
  member: MemberPayload;
  body: IHrmsTimelog.IRequest;
}): Promise<IPageIHrmsTimelog.ISummary> {
  const page = props.body.page ?? 1;
  const limit = props.body.limit ?? 100;
  // Validate page number
  if (page < 1) {
    throw new HttpException("Page must be at least 1", 400);
  }
  // Validate limit
  if (limit < 1 || limit > 100) {
    throw new HttpException("Limit must be between 1 and 100", 400);
  }
  const skip = (page - 1) * limit;
  // Calculate default date range (current calendar week Monday to Sunday)
  const now = new Date();
  const currentDayOfWeek = now.getUTCDay();
  const daysSinceMonday = currentDayOfWeek === 0 ? 6 : currentDayOfWeek - 1;
  const monday = new Date(
    now.getTime() - daysSinceMonday * 24 * 60 * 60 * 1000,
  );
  const sunday = new Date(monday.getTime() + 6 * 24 * 60 * 60 * 1000);
  const startDate =
    props.body.date_range?.start_date ?? toISOStringSafe(monday);
  const endDate = props.body.date_range?.end_date ?? toISOStringSafe(sunday);
  // Determine grouping from metric_types or default to 'employee'
  const validMetricTypes = ["employee", "project", "task"];
  const metricType = props.body.metric_types?.[0];
  const grouping = validMetricTypes.includes(metricType ?? "")
    ? (metricType as "employee" | "project" | "task")
    : "employee";
  // Validate grouping
  if (!validMetricTypes.includes(grouping)) {
    throw new HttpException("Invalid grouping type", 400);
  }
  // Get organization_id from member's organization membership
  const orgMember = await MyGlobal.prisma.hrms_organization_members.findFirst({
    where: {
      hrms_member_id: props.member.id,
    },
    select: { hrms_organization_id: true },
  });
  if (!orgMember) {
    throw new HttpException("Organization membership not found", 404);
  }
  const organizationId = orgMember.hrms_organization_id;
  // Get employee IDs belonging to organization through hrms_organization_members
  const employeeIds = await MyGlobal.prisma.hrms_organization_members.findMany({
    where: {
      hrms_organization_id: organizationId,
    },
    select: { hrms_member_id: true },
  });
  const employeeIdList = employeeIds.map((e) => e.hrms_member_id);
  const timelogs = await MyGlobal.prisma.hrms_timelogs.findMany({
    where: {
      deleted_at: null,
      date: {
        gte: new Date(startDate),
        lte: new Date(endDate),
      },
      employee_id: {
        in: employeeIdList,
      },
    },
    include: {
      project: {
        select: {
          id: true,
          name: true,
        },
      },
      task: {
        select: {
          id: true,
          title: true,
        },
      },
      employee: {
        select: {
          id: true,
          display_name: true,
        },
      },
    },
  });
  // Group by selected criterion
  const grouped = timelogs.reduce(
    (acc, timelog) => {
      const key =
        grouping === "employee"
          ? timelog.employee_id
          : grouping === "project"
            ? timelog.project_id
            : timelog.task_id || "unassigned-task";
      if (!acc[key]) {
        acc[key] = {
          id: key,
          total_hours: 0,
          billable_hours: 0,
          non_billable_hours: 0,
        };
      }
      const hours = timelog.duration_minutes / 60;
      acc[key].total_hours += hours;
      if (timelog.billable) {
        acc[key].billable_hours += hours;
      } else {
        acc[key].non_billable_hours += hours;
      }
      return acc;
    },
    {} as Record<
      string,
      {
        id: string;
        total_hours: number;
        billable_hours: number;
        non_billable_hours: number;
      }
    >,
  );
  // Build response with group names
  const responseData: IHrmsTimelog.ISummary[] = Object.entries(grouped).map(
    ([groupId, data]) => {
      const firstTimelog = timelogs.find((t) =>
        grouping === "employee"
          ? t.employee_id === groupId
          : grouping === "project"
            ? t.project_id === groupId
            : t.task_id === groupId,
      );
      let groupName = "";
      if (grouping === "employee" && firstTimelog?.employee) {
        groupName = firstTimelog.employee.display_name;
      } else if (grouping === "project" && firstTimelog?.project) {
        groupName = firstTimelog.project.name;
      } else if (grouping === "task" && firstTimelog?.task) {
        groupName = firstTimelog.task.title;
      } else if (grouping === "task") {
        groupName = "Unassigned";
      }
      return {
        group_id: groupId as string & tags.Format<"uuid">,
        group_name: groupName,
        total_hours: data.total_hours,
        billable_hours: data.billable_hours,
        non_billable_hours: data.non_billable_hours,
      } satisfies IHrmsTimelog.ISummary;
    },
  );
  // Calculate pagination
  const total = responseData.length;
  const paginatedData = responseData.slice(skip, skip + limit);
  return {
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.ceil(total / limit),
    } satisfies IPage.IPagination,
    data: paginatedData,
  } satisfies IPageIHrmsTimelog.ISummary;
}

import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { IHrmsEmployee } from "@ORGANIZATION/PROJECT-api/lib/structures/IHrmsEmployee";
import { IHrmsProject } from "@ORGANIZATION/PROJECT-api/lib/structures/IHrmsProject";
import { IHrmsTask } from "@ORGANIZATION/PROJECT-api/lib/structures/IHrmsTask";
import { IHrmsTimer } from "@ORGANIZATION/PROJECT-api/lib/structures/IHrmsTimer";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { MemberPayload } from "../decorators/payload/MemberPayload";
import { HrmsTimerTransformer } from "../transformers/HrmsTimerTransformer";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function patchHrmsMemberTimersTimerId(props: {
  member: MemberPayload;
  timerId: string & tags.Format<"uuid">;
  body: IHrmsTimer.IUpdate;
}): Promise<IHrmsTimer> {
  const timer = await MyGlobal.prisma.hrms_timers.findUniqueOrThrow({
    where: { id: props.timerId },
    select: {
      id: true,
      hrms_employee_id: true,
      hrms_project_id: true,
      hrms_task_id: true,
      start_at: true,
      description: true,
      created_at: true,
      updated_at: true,
      deleted_at: true,
      employee: { select: { id: true, status: true } },
    },
  });
  if (timer.hrms_employee_id !== props.member.id) {
    throw new HttpException("Forbidden", 403);
  }
  if (timer.deleted_at !== null) {
    throw new HttpException("Not Found", 404);
  }
  const employee = await MyGlobal.prisma.hrms_employees.findUniqueOrThrow({
    where: { id: timer.hrms_employee_id },
    select: { id: true, status: true },
  });
  if (employee.status !== "active") {
    throw new HttpException("Employee is deactivated", 400);
  }
  const targetProjectId =
    props.body.hrms_project_id !== undefined
      ? props.body.hrms_project_id
      : timer.hrms_project_id;
  if (props.body.hrms_project_id !== undefined) {
    const projectMember = await MyGlobal.prisma.hrms_project_members.findFirst({
      where: {
        employee_id: props.member.id,
        project_id: props.body.hrms_project_id,
      },
      select: { id: true },
    });
    if (projectMember === null) {
      throw new HttpException("Employee is not assigned to this project", 400);
    }
  }
  if (
    props.body.hrms_task_id !== undefined &&
    props.body.hrms_task_id !== null
  ) {
    const task = await MyGlobal.prisma.hrms_tasks.findUniqueOrThrow({
      where: { id: props.body.hrms_task_id },
      select: { id: true, hrms_project_id: true },
    });
    if (task.hrms_project_id !== targetProjectId) {
      throw new HttpException(
        "Task does not belong to the selected project",
        400,
      );
    }
  }
  const updateData: Prisma.hrms_timersUpdateInput = {
    updated_at: new Date(),
  };
  if (props.body.description !== undefined) {
    updateData.description = props.body.description;
  }
  if (props.body.hrms_project_id !== undefined) {
    updateData.project = { connect: { id: props.body.hrms_project_id } };
  }
  if (
    props.body.hrms_task_id !== undefined &&
    props.body.hrms_task_id !== null
  ) {
    updateData.task = { connect: { id: props.body.hrms_task_id } };
  }
  const updatedTimer = await MyGlobal.prisma.hrms_timers.update({
    where: { id: props.timerId },
    data: updateData,
    ...HrmsTimerTransformer.select(),
  });
  return await HrmsTimerTransformer.transform(updatedTimer);
}

import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { IHrmsEmployee } from "@ORGANIZATION/PROJECT-api/lib/structures/IHrmsEmployee";
