export async function patchHrmsMemberTimesheets(props: {
  member: MemberPayload;
  body: IHrmsTimesheet.IRequest;
}): Promise<IPageIHrmsTimesheet.ISummary> {
  // Parse and validate date range
  const startDate: string & tags.Format<"date"> = props.body.start_date;
  const endDate: string & tags.Format<"date"> = props.body.end_date;
  // Validate date order
  if (startDate > endDate) {
    throw new HttpException("Start date must be on or before end date", 400);
  }
  // Validate and normalize pagination parameters
  const page: number & tags.Type<"int32"> & tags.Minimum<1> = (props.body
    .page ?? 1) as number & tags.Type<"int32"> & tags.Minimum<1>;
  const limit: (number & tags.Type<"int32"> & tags.Minimum<0>) | null = (props
    .body.limit ?? 100) as
    | (number & tags.Type<"int32"> & tags.Minimum<0>)
    | null;
  const effectiveLimit: number =
    limit === null || limit === undefined
      ? 100
      : limit > 100
        ? 100
        : limit < 1
          ? 1
          : limit;
  // Verify member's organization membership
  const orgMember = await MyGlobal.prisma.hrms_organization_members.findFirst({
    where: {
      hrms_member_id: props.member.id,
      hrms_organization_id: props.body.organization_id,
      deleted_at: null,
    },
  });
  if (!orgMember) {
    throw new HttpException("Not a member of the specified organization", 403);
  }
  // Build employee_id filter
  const employee = await MyGlobal.prisma.hrms_employees.findFirst({
    where: {
      organization_member_id: orgMember.id,
      deleted_at: null,
    },
  });
  if (!employee) {
    throw new HttpException(
      "Employee record not found for this organization membership",
      404,
    );
  }
  const timesheetEmployeeIdFilter = employee.id;
  // Build timesheet query filters
  const timesheetWeekStartStartDate: string & tags.Format<"date"> = startDate;
  const timesheetWeekStartEndDate: string & tags.Format<"date"> = endDate;
  const timesheetsWhereInput: Prisma.hrms_timesheetsWhereInput = {
    deleted_at: null,
    week_start_date: {
      gte: new Date(`${timesheetWeekStartStartDate}T00:00:00Z`),
      lte: new Date(`${timesheetWeekStartEndDate}T23:59:59Z`),
    },
    hrms_employee_id: timesheetEmployeeIdFilter,
  } satisfies Prisma.hrms_timesheetsWhereInput;
  // Execute queries
  const [timesheets, totalCount] = await Promise.all([
    MyGlobal.prisma.hrms_timesheets.findMany({
      where: timesheetsWhereInput,
      include: {
        employee: {
          select: {
            id: true,
            display_name: true,
            position: true,
            department_id: true,
            status: true,
            _count: {
              select: {
                timelogs: true,
              },
            },
          },
        },
        reviewer: {
          select: {
            id: true,
            email: true,
            display_name: true,
            avatar_uri: true,
            phone_number: true,
            created_at: true,
            updated_at: true,
            deleted_at: true,
          },
        },
      },
      orderBy: [{ week_start_date: "desc" }, { id: "desc" }],
      skip: (page - 1) * effectiveLimit,
      take: effectiveLimit,
    }),
    MyGlobal.prisma.hrms_timesheets.count({
      where: timesheetsWhereInput,
    }),
  ]);
  // Transform timesheets to response format
  const data: IHrmsTimesheet.ISummary[] = await ArrayUtil.asyncMap(
    timesheets,
    async (timesheet) => {
      const employeeData = timesheet.employee;
      const reviewerData = timesheet.reviewer;
      return {
        project_id: "00000000-0000-0000-0000-000000000000" as string &
          tags.Format<"uuid">,
        project_name: "",
        budget_hours: 0,
        actual_hours: 0,
        progress: 0,
        utilization_percentage: 0,
        utilization_flag: false,
        id: timesheet.id as string & tags.Format<"uuid">,
        employee: {
          id: employeeData.id as string & tags.Format<"uuid">,
          display_name: employeeData.display_name,
          position: employeeData.position ?? undefined,
          department_id:
            employeeData.department_id ??
            ("00000000-0000-0000-0000-000000000000" as string &
              tags.Format<"uuid">),
          status: employeeData.status,
          total_hours_logged: 0,
          timelog_count: employeeData._count.timelogs,
          timesheets_submitted: 0,
          timesheets_approved: 0,
          timesheets_pending: 0,
        },
        reviewer:
          reviewerData !== null && reviewerData !== undefined
            ? {
                id: reviewerData.id as string & tags.Format<"uuid">,
                email: reviewerData.email,
                display_name: reviewerData.display_name,
                avatar_uri: reviewerData.avatar_uri ?? null,
                phone_number: reviewerData.phone_number ?? null,
                organization_membership_count: 0,
                created_at: toISOStringSafe(reviewerData.created_at),
                updated_at: toISOStringSafe(reviewerData.updated_at),
                deleted_at:
                  reviewerData.deleted_at !== null &&
                  reviewerData.deleted_at !== undefined
                    ? toISOStringSafe(reviewerData.deleted_at)
                    : null,
              }
            : null,
        timelogs: [],
        week_start_date: toISOStringSafe(timesheet.week_start_date),
        week_end_date: toISOStringSafe(timesheet.week_end_date),
        status: timesheet.status,
        total_hours: Number(timesheet.total_hours),
        submitted_at:
          timesheet.submitted_at !== null &&
          timesheet.submitted_at !== undefined
            ? toISOStringSafe(timesheet.submitted_at)
            : undefined,
        reviewed_at:
          timesheet.reviewed_at !== null && timesheet.reviewed_at !== undefined
            ? toISOStringSafe(timesheet.reviewed_at)
            : undefined,
        rejection_reason: timesheet.rejection_reason,
        created_at: toISOStringSafe(timesheet.created_at),
        updated_at: toISOStringSafe(timesheet.updated_at),
        deleted_at:
          timesheet.deleted_at !== null && timesheet.deleted_at !== undefined
            ? toISOStringSafe(timesheet.deleted_at)
            : null,
      };
    },
  );
  const paginationData: IPage.IPagination = {
    current: page,
    limit: effectiveLimit,
    records: totalCount,
    pages: Math.ceil(totalCount / effectiveLimit),
  };
  return {
    pagination: paginationData,
    data,
  };
}

import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { IHrmsTask } from "@ORGANIZATION/PROJECT-api/lib/structures/IHrmsTask";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { HrmsTaskCollector } from "../collectors/HrmsTaskCollector";
import { MemberPayload } from "../decorators/payload/MemberPayload";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function postHrmsMemberOrganizationsProjectIdTasks(props: {
  member: MemberPayload;
  projectId: string & tags.Format<"uuid">;
  body: IHrmsTask.ICreate;
}): Promise<IHrmsTask.ICreate> {
  // 1. Verify project exists and belongs to current organization context
  const project = await MyGlobal.prisma.hrms_projects.findUniqueOrThrow({
    where: { id: props.projectId },
    select: {
      id: true,
      hrms_organization_id: true,
    },
  });
  // 2. Validate user has project management permission or is project lead
  const projectMembership =
    await MyGlobal.prisma.hrms_project_members.findFirst({
      where: {
        project_id: props.projectId,
        employee_id: props.member.id,
        deleted_at: null,
      },
    });
  if (!projectMembership) {
    throw new HttpException("Not a project member", 403);
  }
  const hasManagePermission = projectMembership.role === "project:manage";
  const isProjectLead = projectMembership.role === "project-lead";
  if (!hasManagePermission && !isProjectLead) {
    throw new HttpException("Forbidden", 403);
  }
  // 3. Validate assigned employee is a project member if provided
  if (props.body.hrms_employee_id !== null) {
    const employeeAssignment =
      await MyGlobal.prisma.hrms_project_members.findFirst({
        where: {
          project_id: props.projectId,
          employee_id: props.body.hrms_employee_id,
          deleted_at: null,
        },
      });
    if (!employeeAssignment) {
      throw new HttpException("Employee is not a project member", 400);
    }
  }
  // 4. Create task using collector
  const created = await MyGlobal.prisma.hrms_tasks.create({
    data: await HrmsTaskCollector.collect({
      body: props.body,
      hrmsProjects: project,
    }),
    select: {
      id: true,
      hrms_project_id: true,
      hrms_employee_id: true,
      hrms_task_id: true,
      title: true,
      description: true,
      status: true,
      priority: true,
      estimated_hours: true,
      due_date: true,
      billable: true,
      created_at: true,
      updated_at: true,
      deleted_at: true,
    },
  });
  // 5. Return task with proper DTO format (only ICreate fields)
  const task: IHrmsTask.ICreate = {
    title: created.title,
    description: created.description !== null ? created.description : undefined,
    status: created.status as "open" | "in-progress" | "completed" | "closed",
    priority: created.priority as "low" | "medium" | "high" | "urgent",
    estimated_hours:
      created.estimated_hours !== null ? created.estimated_hours : undefined,
    due_date:
      created.due_date !== null ? toISOStringSafe(created.due_date) : undefined,
    billable: created.billable !== null ? created.billable : undefined,
    hrms_employee_id:
      created.hrms_employee_id !== null
        ? (created.hrms_employee_id as string & tags.Format<"uuid">)
        : undefined,
  };
  return task;
}

import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { IHrmsGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IHrmsGuest";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function postHrmsAuthGuestJoin(props: {
  ip: string;
  body: IHrmsGuest.IJoin;
}): Promise<IHrmsGuest.IAuthorized> {
  const emailHash = Buffer.from(props.body.email).toString("base64");
  const existing = await MyGlobal.prisma.hrms_guests.findFirst({
    where: { device_fingerprint: emailHash },
  });
  if (existing) {
    throw new HttpException("Email already registered", 409);
  }
  const nowString: string & tags.Format<"date-time"> = new Date().toISOString();
  const id: string & tags.Format<"uuid"> = v4();
  const guest = await MyGlobal.prisma.hrms_guests.create({
    data: {
      id,
      device_fingerprint: emailHash,
      ip_address: props.body.ip ?? null,
      user_agent: null,
      created_at: new Date(),
      updated_at: new Date(),
      deleted_at: null,
    },
  });
  const sessionId: string & tags.Format<"uuid"> = v4();
  const accessExpires: Date = new Date(Date.now() + 60 * 60 * 1000);
  const refreshExpires: Date = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);
  await MyGlobal.prisma.hrms_guest_sessions.create({
    data: {
      id: sessionId,
      hrms_guest_id: guest.id,
      ip: props.body.ip ?? props.ip,
      href: props.body.href,
      referrer: props.body.referrer,
      created_at: new Date(),
      expired_at: accessExpires,
    },
  });
  const tokenPayload = {
    type: "guest" as const,
    id: guest.id,
    session_id: sessionId,
    created_at: nowString,
  };
  const access: string = jwt.sign(tokenPayload, MyGlobal.env.JWT_SECRET_KEY, {
    expiresIn: "1h",
    issuer: "autobe",
  });
  const refreshPayload = {
    ...tokenPayload,
    tokenType: "refresh" as const,
  };
  const refresh: string = jwt.sign(
    refreshPayload,
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "7d",
      issuer: "autobe",
    },
  );
  const expiredAt: string & tags.Format<"date-time"> =
    toISOStringSafe(accessExpires);
  const refreshableUntil: string & tags.Format<"date-time"> =
    toISOStringSafe(refreshExpires);
  const authorizationToken: IAuthorizationToken = {
    access,
    refresh,
    expired_at: expiredAt,
    refreshable_until: refreshableUntil,
  };
  const result: IHrmsGuest.IAuthorized = {
    id: guest.id,
    device_fingerprint: guest.device_fingerprint,
    ip_address: guest.ip_address ?? null,
    user_agent: guest.user_agent ?? null,
    created_at: toISOStringSafe(guest.created_at),
    updated_at: toISOStringSafe(guest.updated_at),
    deleted_at: guest.deleted_at ? toISOStringSafe(guest.deleted_at) : null,
    access,
    refresh,
    expired_at: expiredAt,
    token: authorizationToken,
  };
  return result;
}

import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
