import { putHrmsMemberProjectsProjectId } from "../../../../providers/putHrmsMemberProjectsProjectId";

@Controller("/hrms/member/projects")
export class HrmsMemberProjectsController {
  /**
   * Retrieve a specific project by its unique identifier, returning complete project details for viewing purposes.
   *
   * This operation fetches a single project record from the organization's project inventory, including all metadata such as project name, description, color code for UI visualization, current status (active/archived/completed), budget hours allocation, and optional start/end dates.
   *
   * The retrieved project information is scoped to the user's currently selected organization. Only users with project view permission within the organization can access this operation. The system enforces organization-level data isolation to prevent cross-organization data leakage.
   *
   * Project status affects what actions can be performed on the project: active projects allow new timelog entries and modifications, while archived or completed projects are read-only but preserve all historical data for audit and reporting purposes.
   *
   * @param connection
   * @param projectId The unique identifier of the project to retrieve.
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor member
   * @x-autobe-specification Query hrms_projects table by id where id matches the path parameter and hrms_organization_id matches the user's organization context.
   *
   * Apply organization context validation:
   * 1. Extract user's organization ID from session/authentication context
   * 2. Query WHERE id = projectId AND hrms_organization_id = user_organization_id
   * 3. Return 404 if project not found or not in user's organization
   *
   * Return complete project record with all fields:
   * - id: UUID of the project
   * - hrms_organization_id: Parent organization reference
   * - name: Project name (required)
   * - description: Optional description text
   * - color_code: Hex color code for UI display
   * - status: One of 'active', 'archived', 'completed'
   * - budget_hours: Optional total estimated hours (float)
   * - start_date: Optional project start date
   * - end_date: Optional project end date
   * - created_at: Creation timestamp
   * - updated_at: Last update timestamp
   *
   * Check deleted_at field - if not null, return 404 to hide soft-deleted projects from end users.
   *
   * This operation does not return child relations (tasks, project_members, timelogs) to keep response lightweight. Related operations should be called separately if children are needed.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Get(":projectId")
  public async at(
    @MemberAuth()
    member: MemberPayload,
    @TypedParam("projectId")
    projectId: string & tags.Format<"uuid">,
  ): Promise<IHrmsProject> {
    try {
      return await getHrmsMemberProjectsProjectId({
        member,
        projectId,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Update an existing project's details within an organization.
   *
   * This operation allows users with project management permission to modify project information including the project name, description, color code, status, budget hours, start date, and end date. Projects are organized within organizations, and this operation respects the multi-tenant isolation where projects can only be accessed and modified by members of the owning organization.
   *
   * The operation validates that the requesting user has appropriate permissions before allowing the update. Only editable fields can be modified; any fields not included in the request body will remain unchanged. The status field can transition projects to different states, but status changes are subject to business rules - for example, once a project is completed, it cannot receive new timelogs but existing timelogs remain preserved.
   *
   * All changes are immediately visible to users with project view permission. The updated_at timestamp is automatically refreshed to reflect the modification time. The project remains associated with its organization and maintains all existing relationships with tasks, project members, and timelogs.
   *
   * @param connection
   * @param projectId Unique identifier of the project to update
   * @param body Project update data containing editable fields
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor member
   * @x-autobe-specification Query the hrms_projects table for the project record matching the projectId path parameter.
   *
   * Validate that:
   * 1. The project exists in the database
   * 2. The project belongs to the requesting user's organization context
   * 3. The requesting user has project management permission within that organization
   * 4. If status is being changed, verify the new status is valid (active, archived, or completed)
   * 5. If status is changing to completed, verify no new timelogs can be added (business rule enforcement)
   *
   * Apply the update to the project record with the following field mappings from request body:
   * - name: required, must not be empty
   * - description: optional, can be null or string
   * - color_code: required, must be a valid hex color format
   * - status: optional, must be one of: 'active', 'archived', 'completed'
   * - budget_hours: optional, numeric value representing estimated hours
   * - start_date: optional, date for project timeline planning
   * - end_date: optional, date for project timeline planning
   *
   * Set updated_at timestamp to current time (DateTime.now()) before persisting.
   *
   * Return the complete updated project object including all fields.
   *
   * Handle error cases:
   * - 404 Not Found: project does not exist
   * - 403 Forbidden: user lacks project management permission
   * - 400 Bad Request: validation failed (empty name, invalid color code format, invalid status value, missing required fields)
   * - 409 Conflict: project cannot be completed because it has active timelogs requiring review
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Put(":projectId")
  public async update(
    @MemberAuth()
    member: MemberPayload,
    @TypedParam("projectId")
    projectId: string & tags.Format<"uuid">,
    @TypedBody()
    body: IHrmsProject.IUpdate,
  ): Promise<IHrmsProject> {
    try {
      return await putHrmsMemberProjectsProjectId({
        member,
        projectId,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Permanently removes a project from the organization along with all associated tasks and project memberships.
   *
   * This operation requires strict validation before execution: the project must have zero associated timelogs, and the requesting user must have project:manage permission for the project's organization. Projects with any time tracking history cannot be deleted to preserve historical data integrity.
   *
   * When a project is deleted, all child entities are cascade-deleted: all tasks belonging to the project are removed, all project member assignments are deleted, and the project record itself is permanently removed from the database. There is no recovery option for deleted projects.
   *
   * The operation is logged in the organization's activity log for audit purposes, recording the project name, deletion timestamp, and the user who performed the deletion. No notifications are sent when a project is deleted.
   *
   * Users should archive or complete projects with existing timelogs instead of deleting them. Archived or completed projects preserve all historical timelog data while preventing new time entries.
   *
   * @param connection
   * @param projectId Unique identifier of the project to delete
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor member
   * @x-autobe-specification 1. Fetch project by projectId from hrms_projects table
   * 2. Verify user has project:manage permission for the project's organization
   * 3. Validate deletion conditions:
   *    - Count timelogs associated with this project (via hrms_timelogs.project_id)
   *    - If timelog count > 0, return 409 Conflict with message 'Project has associated timelogs'
   *    - Count active tasks with status 'todo', 'in_progress', or 'in_review'
   *    - If any active tasks exist, return 409 Conflict with message 'Project has active tasks'
   * 4. Begin transaction:
   *    - Delete all hrms_project_members where project_id = projectId
   *    - Delete all hrms_tasks where project_id = projectId
   *    - Delete hrms_projects record where id = projectId
   * 5. Log activity in hrms_activity_logs: { organization_id, performed_by: userId, action: 'project_deleted', details: { project_name, project_id } }
   * 6. Return deleted project data in response
   * 7. If transaction fails, return 500 Internal Server Error
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Delete(":projectId")
  public async erase(
    @MemberAuth()
    member: MemberPayload,
    @TypedParam("projectId")
    projectId: string & tags.Format<"uuid">,
  ): Promise<void> {
    try {
      return await deleteHrmsMemberProjectsProjectId({
        member,
        projectId,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Retrieve a personalized project dashboard for the authenticated user, showing their assigned projects with key metrics and status information.
   *
   * This endpoint provides a summary view of all projects where the user is a member, including budget utilization tracking, task assignments, and project status indicators. The dashboard shows budget consumption percentages for each project, with projects exceeding 80% utilization highlighted for management attention.
   *
   * Security considerations: Users can only access projects where they have an active membership. The response includes only essential information optimized for dashboard display, avoiding nested arrays that could cause performance issues. Project leads have visibility to task-level details for projects they lead, while regular members see high-level status only.
   *
   * @param connection
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor member
   * @x-autobe-specification Query hrms_project_members table for all active memberships where employee_id matches the authenticated user's ID.
   *
   * Join with hrms_projects to retrieve project details including budget_hours, status, and dates.
   *
   * For each project membership:
   * - Calculate budget utilization percentage: (SUM of actual timelogs / budget_hours) * 100, rounded to 1 decimal
   * - Only include projects where the employee is assigned (project_member.status = 'active')
   * - If budget_hours is NULL, exclude from budget utilization calculation
   * - Set budget_utilization_percent to 0 for projects with no budget allocated
   *
   * Join with hrms_tasks to count tasks by status (open, in_progress, completed, closed) for the user's assigned tasks.
   *
   * Filter out soft-deleted records (deleted_at IS NULL) from projects, tasks, and project_memberships.
   *
   * Sort results by created_at descending (newest projects first).
   *
   * Include project_lead status in response to differentiate between lead and member roles.
   *
   * Return response wrapped in IProjectDashboard type with total_projects, budget_overview, and projects array.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Get("dashboard")
  public async dashboard(
    @MemberAuth()
    member: MemberPayload,
  ): Promise<IHrmsProject> {
    try {
      return await getHrmsMemberProjectsDashboard({
        member,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

